// Generated by vibelang from worker/FeedLocks.ts; the migrate flow writes it again with each batch.
import { Effect } from "effect";
const keyOf = (pair) => `feed:${pair.repoId ?? ""}:${pair.personId}`;
/** `pairs` as their lock keys, de-duplicated and sorted: the one order. */
export const keysOf = (pairs) => [...new Set([...pairs].map(keyOf))].sort();
/**
 * Takes the locks of `pairs` for the rest of the caller's transaction, in the one order. Answers the keys it holds:
 * a writer touches only rows of a pair among them.
 */
export const lock = (sql, pairs) => Effect.gen(function* () {
    const keys = keysOf(pairs);
    for (const key of keys)
        yield* sql `SELECT pg_advisory_xact_lock(hashtextextended(${key}, 0))`;
    return new Set(keys);
});
/** Whether `held` (from `lock`) covers `pair`. */
export const holds = (held, pair) => held.has(keyOf(pair));
